begin;
alter table public.v26_profiles add column listed boolean not null default false,add column share_passport boolean not null default false,add column cover text not null default 'Emerald';
create table voyage_private.invites(record uuid references public.v26_records on delete cascade,recipient uuid references auth.users on delete cascade,primary key(record,recipient));
create index on voyage_private.invites(recipient);
create table voyage_private.links(actor uuid references auth.users on delete cascade,target uuid references auth.users on delete cascade,kind text check(kind in ('follow','block','mute')),at timestamptz default now(),primary key(actor,target,kind),check(actor<>target));
create table voyage_private.reactions(actor uuid references auth.users on delete cascade,post uuid references public.v26_posts on delete cascade,kind text check(kind in ('like','save')),at timestamptz default now(),primary key(actor,post,kind));
create function voyage_private.visible(a uuid,b uuid) returns boolean language sql stable as $$select not exists(select 1 from voyage_private.links where (actor=a and target=b and kind in ('mute','block')) or (target=a and actor=b and kind='block'))$$;
create function public.v26_privacy(list_profile boolean,show_stamps boolean,colour text) returns void language plpgsql security definer set search_path='' as $$begin if not public.v26_active() or colour not in ('Emerald','Midnight','Champagne') then raise exception 'Invalid settings';end if;update public.v26_profiles set listed=list_profile,share_passport=(list_profile and show_stamps),cover=colour where id=auth.uid();end$$;
create function public.v26_people(term text default '') returns table(username text,cover text) language sql stable security definer set search_path='' as $$select p.username,p.cover from public.v26_profiles p where p.listed and not p.suspended and (select community from voyage_private.settings) and starts_with(p.username,lower(trim(term))) and voyage_private.visible(auth.uid(),p.id) order by p.username limit 40$$;
create function public.v26_passport(handle text) returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('name',p.username,'cover',p.cover,'stamps',(select coalesce(jsonb_agg(x.name order by x.name),'[]') from (select distinct left(r.data->'place'->>'name',150) name from public.v26_records r where r.owner=p.id and r.kind='visit' and r.data->>'status'='Visited' and r.data->'place'->>'type' in ('Country','Territory')) x)) from public.v26_profiles p where p.username=lower(handle) and p.listed and p.share_passport and not p.suspended and voyage_private.visible(auth.uid(),p.id) and (select community from voyage_private.settings)$$;
create function public.v26_link(handle text,op text,enabled boolean) returns void language plpgsql security definer set search_path='' as $$declare uid uuid;begin
if not public.v26_active() or op not in ('follow','block','mute') then raise exception 'Active account required';end if;
select id into uid from public.v26_profiles where username=lower(handle) and not suspended;
if uid is null or uid=auth.uid() then raise exception 'Unknown traveller';end if;
if enabled then perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text,0));if (select count(*) from voyage_private.links where actor=auth.uid())>=1000 then raise exception 'Limit reached';end if;
if op='follow' and (not voyage_private.visible(auth.uid(),uid) or not exists(select 1 from public.v26_people(handle) where username=handle)) then raise exception 'Follow unavailable';end if;
insert into voyage_private.links(actor,target,kind) values(auth.uid(),uid,op) on conflict do nothing;
if op='block' then delete from voyage_private.links where kind='follow' and ((actor=auth.uid() and target=uid) or (actor=uid and target=auth.uid()));end if;
else delete from voyage_private.links where actor=auth.uid() and target=uid and kind=op;end if;end$$;
create or replace function public.v26_feed(filter_kind text default '',place_name text default '',page_no int default 0) returns table(id uuid,kind text,destination text,title text,body text,scores jsonb,username text,created_at timestamptz) language sql stable security definer set search_path='' as $$select f.id,f.kind,f.destination,f.title,f.body,f.scores,p.username,f.created_at from public.v26_posts f join public.v26_profiles p on p.id=f.owner where (select community from voyage_private.settings) and not p.suspended and voyage_private.visible(auth.uid(),p.id) and f.status='published' and (filter_kind='' or filter_kind=f.kind) and (place_name='' or lower(place_name)=lower(f.destination)) order by f.created_at desc,f.id limit 25 offset greatest(0,least(page_no,10000))*25$$;
create function public.v26_react(pid uuid,op text,enabled boolean) returns void language plpgsql security definer set search_path='' as $$begin
if not public.v26_active() or op not in ('like','save') then raise exception 'Active account required';end if;if not enabled then delete from voyage_private.reactions where actor=auth.uid() and post=pid and kind=op;return;end if;
if not(select community from voyage_private.settings) or not exists(select 1 from public.v26_posts f join public.v26_profiles p on p.id=f.owner where f.id=pid and f.status='published' and not p.suspended and voyage_private.visible(auth.uid(),p.id)) then raise exception 'Post unavailable';end if;
perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text,0));if (select count(*) from voyage_private.reactions where actor=auth.uid())>=2000 then raise exception 'Limit reached';end if;insert into voyage_private.reactions(actor,post,kind) values(auth.uid(),pid,op) on conflict do nothing;end$$;
create function public.v26_share(rid uuid,handle text,enabled boolean) returns void language plpgsql security definer set search_path='' as $$declare uid uuid;begin if not public.v26_active() or not exists(select 1 from public.v26_records where id=rid and owner=auth.uid() and kind in ('trip','journal')) then raise exception 'Only an active owner may share';end if;
select id into uid from public.v26_profiles where username=lower(handle) and not suspended;if uid is null or uid=auth.uid() then raise exception 'Unknown recipient';end if;
if enabled then perform pg_advisory_xact_lock(hashtextextended(rid::text,0));if not voyage_private.visible(auth.uid(),uid) or (select count(*) from voyage_private.invites where record=rid)>=20 then raise exception 'Sharing unavailable';end if;insert into voyage_private.invites values(rid,uid) on conflict do nothing;
else delete from voyage_private.invites where record=rid and recipient=uid;end if;end$$;
create function public.v26_shared() returns table(record_id uuid,kind text,username text,data jsonb) language sql stable security definer set search_path='' as $$select r.id,r.kind,p.username,case when r.kind='trip' then jsonb_build_object('title',r.data->'title','start',r.data->'start','end',r.data->'end','stops',r.data->'stops') else jsonb_build_object('title',r.data->'title','date',r.data->'date','place',r.data->'place','story',r.data->'story') end from voyage_private.invites i join public.v26_records r on i.record=r.id join public.v26_profiles p on p.id=r.owner where i.recipient=auth.uid() and public.v26_active() and not p.suspended and voyage_private.visible(auth.uid(),p.id) order by r.created_at desc limit 100$$;
create function public.v26_social() returns jsonb language plpgsql stable security definer set search_path='' as $$begin if not public.v26_active() then raise exception 'Active account required';end if;return jsonb_build_object('prefs',(select jsonb_build_object('listed',listed,'passport',share_passport,'cover',cover) from public.v26_profiles where id=auth.uid()),'links',(select coalesce(jsonb_agg(jsonb_build_object('handle',p.username,'kind',l.kind)),'[]') from voyage_private.links l join public.v26_profiles p on p.id=l.target where l.actor=auth.uid()),'followers',(select coalesce(jsonb_agg(x),'[]') from (select p.username,l.at from voyage_private.links l join public.v26_profiles p on p.id=l.actor where l.kind='follow' and l.target=auth.uid() and not p.suspended and voyage_private.visible(auth.uid(),p.id) order by l.at desc limit 40)x),'saved',(select coalesce(jsonb_agg(x),'[]') from (select f.id,f.title,f.body,r.kind from voyage_private.reactions r join public.v26_posts f on f.id=r.post join public.v26_profiles p on p.id=f.owner where r.actor=auth.uid() and f.kind<>'comment' and f.status='published' and not p.suspended and voyage_private.visible(auth.uid(),f.owner) and (select community from voyage_private.settings) order by r.at desc limit 2000)x));end$$;
create function public.v26_scores(place_name text) returns table(category text,reviews bigint,average numeric,one bigint,two bigint,three bigint,four bigint,five bigint) language sql stable security definer set search_path='' as $$select e.key,count(*),round(avg(e.value::int),2),count(*) filter(where e.value='1'),count(*) filter(where e.value='2'),count(*) filter(where e.value='3'),count(*) filter(where e.value='4'),count(*) filter(where e.value='5') from public.v26_posts f join public.v26_profiles p on p.id=f.owner cross join lateral jsonb_each_text(f.scores)e where (select community from voyage_private.settings) and not p.suspended and f.kind='review' and f.status='published' and lower(f.destination)=lower(place_name) group by e.key order by e.key$$;
do $$declare f regprocedure;begin for f in select oid::regprocedure from pg_proc where pronamespace='public'::regnamespace and proname in ('v26_privacy','v26_people','v26_passport','v26_link','v26_react','v26_share','v26_shared','v26_social','v26_scores') loop execute format('revoke all on function %s from public,anon,authenticated',f);execute format('grant execute on function %s to authenticated',f);end loop;end$$;
grant execute on function public.v26_people(text),public.v26_passport(text),public.v26_scores(text) to anon;
commit;
